import{_t as e,it as t,n,rt as r}from"./chunks/framework.DJFGRv8Z.js";var i=JSON.parse(`{"title":"开发者 API","description":"","frontmatter":{},"headers":[],"relativePath":"guide/developer-api.md","filePath":"guide/developer-api.md","lastUpdated":1788621106000}`),a={name:`guide/developer-api.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="开发者-api" tabindex="-1">开发者 API <a class="header-anchor" href="#开发者-api" aria-label="Permalink to “开发者 API”">​</a></h1><h2 id="创建密钥" tabindex="-1">创建密钥 <a class="header-anchor" href="#创建密钥" aria-label="Permalink to “创建密钥”">​</a></h2><p>在“管理 → 开发者”创建个人 API Key，并只授予业务需要的作用域。完整密钥只显示一次；丢失后撤销旧密钥并重新创建。</p><p>请求地址、鉴权格式和当前接口定义以应用内 OpenAPI 页面 <a href="https://to9.us/app/manage/developer/docs" target="_blank" rel="noreferrer">https://to9.us/app/manage/developer/docs</a> 为准。基本格式：</p><div class="language-http"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">http</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">Authorization</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Bearer &lt;API_KEY&gt;</span></span>
<span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">Accept</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> application/json</span></span></code></pre></div><p>不要把真实密钥写进浏览器前端、公开仓库、日志、截图或工单。服务端程序通过环境变量或密钥管理服务注入。</p><h2 id="作用域" tabindex="-1">作用域 <a class="header-anchor" href="#作用域" aria-label="Permalink to “作用域”">​</a></h2><p>API Key 可按资源限制邮件、邮箱、联系人、文件夹、标签、规则、签名、存储和附件等权限。读写操作还会继续执行当前用户的资源归属、组织角色、共享范围和配额检查。</p><p>邮箱共享是只读能力，不会因为调用 API 自动获得发信、改邮箱设置或创建客户端密码的权限。</p><p>创建和列出 API Key、修改密码、OAuth 绑定、找回邮箱、TOTP 和应用专用密码等凭据操作只允许真实浏览器会话，并拒绝管理员代入会话或 API Key 自身调用。</p><h2 id="分页与筛选" tabindex="-1">分页与筛选 <a class="header-anchor" href="#分页与筛选" aria-label="Permalink to “分页与筛选”">​</a></h2><p>列表接口可能使用 <code>page</code>、<code>limit</code>、搜索词、状态、邮箱、文件夹、标签或时间范围。客户端应遵守服务端返回的总数和边界，不能假设空页代表资源不存在。</p><p>邮件查询只返回调用者有权访问的邮箱；受限共享不会通过“全部邮箱”统计泄露未授权目录数量。</p><h2 id="响应与错误" tabindex="-1">响应与错误 <a class="header-anchor" href="#响应与错误" aria-label="Permalink to “响应与错误”">​</a></h2><table tabindex="0"><thead><tr><th>状态</th><th>含义</th></tr></thead><tbody><tr><td><code>2xx</code></td><td>请求成功</td></tr><tr><td><code>400</code></td><td>参数或业务状态不符合要求</td></tr><tr><td><code>401</code></td><td>凭据无效、过期或已撤销</td></tr><tr><td><code>403</code></td><td>作用域、资源权限或代入会话限制</td></tr><tr><td><code>404</code></td><td>资源不存在或当前身份不可见</td></tr><tr><td><code>409</code></td><td>唯一性、并发或当前状态冲突</td></tr><tr><td><code>429</code></td><td>请求、注册、登录或协议频率过高</td></tr><tr><td><code>5xx</code></td><td>服务端或依赖暂时失败</td></tr></tbody></table><p>安全敏感路径会把数据库、凭据和第三方详细错误留在受限服务端日志，并向客户端返回概括性错误；客户端仍不应依赖任意错误正文作为稳定协议，也不应把响应原样公开。排障时记录请求时间、路径、状态码和安全处理后的关联信息。</p><h2 id="重试与幂等" tabindex="-1">重试与幂等 <a class="header-anchor" href="#重试与幂等" aria-label="Permalink to “重试与幂等”">​</a></h2><p>客户端设置连接和读取超时。对网络错误和部分 <code>5xx</code> 使用带随机抖动的指数退避。发送邮件、创建订单、转让邮箱、兑换和删除等有副作用请求不能盲目重试；先查询最终状态或使用接口提供的幂等机制。</p><h2 id="密钥轮换" tabindex="-1">密钥轮换 <a class="header-anchor" href="#密钥轮换" aria-label="Permalink to “密钥轮换”">​</a></h2><ol><li>创建权限相同或更小的新密钥。</li><li>更新应用配置并验证请求成功。</li><li>撤销旧密钥。</li><li>检查审计记录，确认没有旧密钥流量。</li></ol>`,20)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};